    $ch1Story = "प्राचीन काल में एक सुन्दर नगर था — सुवर्णपुर। वहाँ एक धनी साहूकार रहता था, जिसका नाम धनपाल था। उसका व्यापार दूर-दूर तक फैला हुआ था। उसके घर में धन-धान्य की कोई कमी नहीं थी। सोने के बर्तनों में भोजन परोसा जाता, चाँदी के दीपक जलते और रेशम के वस्त्र पहने जाते। परन्तु धनपाल की सबसे बड़ी सम्पत्ति उसके सात पुत्र थे। सातों बेटे रूप में कामदेव के समान, बुद्धि में बृहस्पति के समान और सेवा में साक्षात् धर्मराज के समान थे। उनके घर में सदा हँसी-खुशी का वातावरण रहता था।\n\nधनपाल की पत्नी का नाम सुभद्रा था। वह परम सती, शीलवती और भगवान की भक्त थी। वह प्रतिदिन प्रातः स्नान करके माँ लक्ष्मी और श्रीगणेश का पूजन करती और अपने सातों पुत्रों के लिए आशीर्वाद माँगती —\n\n“हे माँ लक्ष्मी! मेरे पुत्रों की आयु बढ़ाओ। उन्हें सदा सुखी रखो।”\n\nसातों पुत्र अपनी माता के अत्यन्त प्रिय थे। वे माता के आदेश का पालन करते और घर में सदा सुख-शान्ति बनी रहती। नगरवासी सुभद्रा को देखकर कहते —\n\n“यह स्त्री धन्य है, जिसके सात पुत्र हैं और जिसका घर सुख-समृद्धि से भरा है।”\n\nपरन्तु सुभद्रा के जीवन में जो घटना घटने वाली थी, वह उसके सुख को छिन्न-भिन्न कर देने वाली थी। उस दिन कार्तिक मास का शुक्ल पक्ष चल रहा था और दीपावली निकट आ रही थी। घर को स्वच्छ और सुसज्जित करने का समय था। सुभद्रा ने अपनी सास और ननदों के साथ विचार किया कि घर की दीवारों को गोबर-मिट्टी से लीपा जाए, जिससे घर पवित्र और सुगन्धित हो जाए।\n\nसुभद्रा ने अपने सातों पुत्रों से कहा —\n\n“पुत्रों! कल हमें घर की दीवारों को लीपना है। तुम लोग खेत की ओर से अच्छी मिट्टी ले आओ।”\n\nपुत्रों ने प्रसन्न होकर कहा —\n\n“माता! हम कल प्रातः ही मिट्टी ले आएँगे।”\n\nउस रात सुभद्रा ने सोचा — “कल मैं स्वयं मिट्टी लेने जाऊँगी। घर को दीपावली के लिए सजाना है।” उसने मन में यह भी सोचा कि पुत्रों को अधिक परिश्रम न करना पड़े।\n\nप्रातःकाल सुभद्रा ने स्नान किया, माँ लक्ष्मी का ध्यान किया और एक टोकरी तथा कुदाली लेकर मिट्टी लेने चल पड़ी। उसके साथ उसकी दो ननदें भी थीं। वे खेत के किनारे पहुँचीं, जहाँ अच्छी चिकनी मिट्टी थी। सुभद्रा ने कुदाली से मिट्टी खोदनी आरम्भ की।\n\nवह स्थान ऐसा था जहाँ एक साही (सेह) का बिल था। साही माता अपने छोटे-छोटे बच्चों के साथ वहाँ रहती थी। उस सुबह साही माता अपने बच्चों के लिए भोजन की खोज में दूर गई हुई थी और बिल में उसके पाँच नन्हे बच्चे सो रहे थे। वे इतने छोटे थे कि उनका शरीर किसी कपास के गोले जैसा लगता था।\n\nसुभद्रा को यह ज्ञान नहीं था कि वह किस स्थान पर कुदाली चला रही है। उसके मन में केवल एक ही विचार था — “घर को दीपावली के लिए सजाना है।” उसने कुदाली को जोर से मिट्टी में मारा। कुदाली की धार उस बिल तक पहुँच गई, जहाँ साही के बच्चे सो रहे थे।\n\nएक ही प्रहार में पाँचों नन्हे बच्चे कटकर मिट्टी में गिर पड़े। उनके शरीर से रक्त बहने लगा। सुभद्रा ने जब मिट्टी हटाई, तो उसने देखा — छोटे-छोटे जीवों के टुकड़े पड़े हैं। उसका हृदय काँप उठा। उसने कुदाली गिरा दी और हाथ जोड़कर बोली —\n\n“हे भगवान! मैंने यह क्या किया? मुझे ज्ञान नहीं था कि यहाँ कोई जीव रहता है। मैंने अज्ञानवश यह पाप किया है।”\n\nननदें भी भयभीत हो गईं। उन्होंने कहा —\n\n“भाभी! यह तो बहुत बड़ा पाप हो गया। साही के बच्चे मारे गए। अब क्या होगा?”\n\nसुभद्रा ने काँपती आवाज़ में कहा —\n\n“मैंने जान-बूझकर नहीं किया। परन्तु पाप तो पाप है। मुझे प्रायश्चित करना चाहिए।”\n\nपरन्तु उस समय तक जो होना था, वह हो चुका था। उन्हें क्या पता था कि उस दिन की यह भूल उनके जीवन को बदल देने वाली है।\n\nदोपहर के समय साही माता भोजन लेकर लौटी। वह अपने बच्चों के पास पहुँची और उसने जो देखा, वह उसके हृदय को चीर देने वाला दृश्य था। उसके पाँचों बच्चे मिट्टी में लहूलुहान पड़े थे। साही माता ने आकाश की ओर हाथ उठाए और चीखकर कहा —\n\n“हे भगवान! यह किसने किया? किस निर्दयी ने मेरे नन्हे बच्चों को मार डाला? जो मेरे प्राणों के समान थे, वे अब नहीं रहे।”\n\nवह रोने-चिल्लाने लगी। उसके आँसू मिट्टी में गिरने लगे। थोड़ी देर में उसे पता चला कि यह कार्य साहूकार की स्त्री सुभद्रा ने किया है। साही माता का हृदय शोक और क्रोध से भर गया। वह उस स्थान से चलकर सुभद्रा के घर के द्वार पर पहुँची।\n\nसुभद्रा उस समय आँगन में बैठी थी और अपने किए पर पछता रही थी। साही माता ने उसे देखा और कठोर स्वर में कहा —\n\n“सुभद्रा! तूने मेरे पाँचों बच्चों को मार डाला। तूने मेरा सर्वस्व छीन लिया। मैं तुझे श्राप देती हूँ — जैसे तूने मेरे बच्चों को मारा है, वैसे ही तेरे सातों पुत्र भी मरेंगे! तू भी वही शोक सहेगी जो मैं सह रही हूँ।”\n\nसुभद्रा के हाथ-पैर ठण्डे हो गए। वह साही माता के चरणों में गिर पड़ी —\n\n“माता! मैंने अज्ञानवश यह पाप किया। मुझे ज्ञान नहीं था कि वहाँ तुम्हारे बच्चे हैं। मैंने जान-बूझकर नहीं किया। कृपया मुझे क्षमा करो। मेरे पुत्रों को श्राप मत दो।”\n\nसाही माता ने क्रोध से कहा —\n\n“सुभद्रा! तूने भी तो नहीं सोचा कि मिट्टी खोदने से किसी जीव की हानि हो सकती है। तूने अपने घर की सजावट के लिए मेरे बच्चों की जान ले ली। अब तू भी अपने बच्चों का शोक सह।”\n\nयह कहकर साही माता वहाँ से चली गई। सुभद्रा रोती-बिलखती रह गई। उसने मन में सोचा —\n\n“हे माँ लक्ष्मी! हे भगवान! अब क्या होगा? मेरे सातों पुत्र मेरे प्राणों के समान हैं। यदि वे मर गए, तो मेरा जीवन अधूरा हो जाएगा।”\n\nसुभद्रा ने अपने पति धनपाल को सारी घटना सुनाई। धनपाल ने कहा —\n\n“पत्नी! तुमने अज्ञानवश यह पाप किया है। हमें किसी ज्ञानी या साधु से इसका प्रायश्चित पूछना चाहिए। परन्तु जो हुआ, वह हो चुका। अब भगवान ही रक्षा करेंगे।”\n\nपरन्तु साही माता के श्राप का प्रभाव तो अटल था। कुछ ही समय पश्चात उस घर में जो हुआ, उसने सारे नगर को स्तब्ध कर दिया। सुभद्रा के सातों पुत्र एक-एक करके बीमार पड़ने लगे और उनके प्राण पंखेरू के समान उड़ने लगे।\n\nसुभद्रा अपने पुत्रों की मृत्यु का दृश्य देखकर पागल होने को थी। उसने आकाश की ओर हाथ उठाकर पुकारा —\n\n“हे माँ लक्ष्मी! हे भगवान! अब मैं क्या करूँ? मेरे जीवन का कोई अर्थ नहीं रहा।”\n\nधनपाल का घर, जो पहले हँसी-खुशी से भरा था, अब श्मशान के समान नीरव हो गया। नगरवासी आश्चर्य से देखने लगे — “इतने धर्मात्मा साहूकार के साथ यह कैसा संकट आया?”\n\nपरन्तु जैसा कि कहा जाता है — जहाँ संकट होता है, वहीं भगवान का द्वार होता है। सुभद्रा के जीवन में एक ऐसी स्त्री आने वाली थी, जो उसे माँ अहोई के व्रत का महात्म्य बताएगी और उसके सूने जीवन में फिर से प्रकाश भर देगी।";

    $ch2Title = "सुभद्रा की विलाप और माँ अहोई का व्रत-महात्म्य";
    $ch2Story = "सुभद्रा के सातों पुत्रों की मृत्यु के बाद उसका घर सूनापन से भर गया। जो आँगन कभी बच्चों की किलकारियों से गूँजता था, वहाँ अब केवल सन्नाटा था। जो दीवारें कभी हँसी से चमकती थीं, वे अब आँसुओं से भीगी रहती थीं। सुभद्रा दिन-रात अपने पुत्रों की याद में रोती रहती —\n\n“हे मेरे लाल! तुम कहाँ गए? मुझे छोड़कर क्यों चले गए? मैंने तो तुम्हारे लिए ही जिया था।”\n\nधनपाल भी शोक में डूब गया। उसका व्यापार ठप्प हो गया। वह न घर में रहता, न बाहर। वह श्मशान में बैठकर घंटों तक अपने बेटों को याद करता। नगरवासी उन्हें देखकर कहते —\n\n“यह कैसा न्याय है? जिसके पास सब कुछ था, वह सब कुछ खो बैठा।”\n\nपरन्तु सुभद्रा के हृदय में एक बात कचोटती रहती थी — वह साही माता की करुण पुकार। उसे याद आता कि साही माता ने कहा था — “तू भी वही शोक सहेगी जो मैं सह रही हूँ।” अब सुभद्रा को समझ आया कि साही माता का श्राप कितना सच्चा था। उसने मन में सोचा —\n\n“मैंने उस निर्दोष जीव के बच्चों की जान ली, जिसका कोई अपराध नहीं था। मैंने अपने घर की सजावट के लिए उसका सर्वस्व छीन लिया। अब मैं उसी शोक से गुजर रही हूँ। यह मेरे ही कर्मों का फल है।”\n\nएक दिन सुभद्रा अपने पुत्रों के कमरे में बैठी थी। उसने उनके खिलौने, उनके वस्त्र और उनकी पुस्तकें देखीं। उसका हृदय फटने लगा। उसने माँ लक्ष्मी की प्रतिमा के सम्मुख हाथ जोड़कर कहा —\n\n“हे माँ! मैंने जान-बूझकर पाप नहीं किया। मुझे क्षमा करो। मेरे पुत्रों को जीवनदान दो। मैं कोई भी प्रायश्चित करने को तैयार हूँ।”\n\nउसी रात सुभद्रा को स्वप्न में एक दिव्य स्त्री के दर्शन हुए। उनका रूप ऐसा था मानो स्वयं माँ लक्ष्मी प्रकट हुई हों। उन्होंने कहा —\n\n“पुत्रि! तेरा शोक जानती हूँ। तूने अज्ञानवश पाप किया है, परन्तु तेरा हृदय शुद्ध है। तूने साही माता के बच्चों की हत्या की है, जिसका प्रायश्चित आवश्यक है। सुनो — कार्तिक मास की कृष्ण अष्टमी को अहोई अष्टमी का व्रत किया जाता है। यह व्रत माँ अहोई को समर्पित है। माँ अहोई साही माता के बच्चों की अधिष्ठात्री देवी हैं। जो स्त्री इस व्रत को श्रद्धा से करती है, उसके सभी पुत्र-सुख लौट आते हैं और साही माता के बच्चों की हत्या का पाप भी नष्ट हो जाता है।”\n\nसुभद्रा ने स्वप्न में पूछा —\n\n“माँ! यह व्रत कैसे किया जाता है? मुझे विधि बताइए।”\n\nदिव्य स्त्री ने कहा —\n\n“पुत्रि! सुनो —\n\n1. प्रातः स्नान एवं संकल्प: अष्टमी के दिन प्रातः स्नान करके स्वच्छ वस्त्र पहनो। माँ अहोई के सम्मुख बैठकर हाथ में जल और अक्षत लेकर संकल्प करो कि ‘मैं अपने पुत्रों की रक्षा और साही माता के बच्चों के प्रायश्चित के लिए यह व्रत करूँगी।’\n2. व्रत: दिनभर निर्जला या फलाहार रहो। किसी भी जीव को हानि मत पहुँचाओ।\n3. दीवार पर चित्र: सायंकाल दीवार पर गेरू या चूने से माँ अहोई का चित्र बनाओ और उनके साथ साही माता एवं उसके बच्चों का चित्र बनाओ। माँ अहोई को सुहाग सामग्री अर्पित करो।\n4. पूजन: माँ अहोई और साही माता का विधिवत पूजन करो। गुड़, चावल, खीर, पूरी और हलवा का भोग लगाओ।\n5. कथा श्रवण: अहोई अष्टमी की कथा श्रद्धापूर्वक सुनो।\n6. तारों के दर्शन: रात्रि में तारों के दर्शन के बाद पारण करो। छलनी से तारे देखकर माँ अहोई को प्रणाम करो。\n\nजो स्त्री यह व्रत श्रद्धा से करती है, उसके पुत्रों की रक्षा होती है और संतान-सुख सदा बना रहता है।”\n\nसुभद्रा ने स्वप्न में हाथ जोड़कर कहा —\n\n“माँ! मैं यह व्रत अवश्य करूँगी। मेरे पुत्रों को जीवनदान दो।”\n\nप्रातःकाल सुभद्रा ने अपना स्वप्न अपने पति धनपाल को सुनाया। धनपाल ने कहा —\n\n“पत्नी! यह माँ अहोई की कृपा है। हमें यह व्रत अवश्य करना चाहिए।”\n\nउसी दिन से सुभद्रा ने अहोई अष्टमी के व्रत की तैयारी आरम्भ की। उसने अपने घर को स्वच्छ किया, दीवारों को गेरू से पोता और माँ अहोई के लिए एक पवित्र स्थान चुना।\n\nकार्तिक मास की कृष्ण अष्टमी का दिन आया। सुभद्रा ने प्रातः ब्रह्ममुहूर्त में स्नान किया। उसने स्वच्छ वस्त्र पहने और माँ अहोई के सम्मुख बैठकर संकल्प लिया —\n\n“ॐ अहोई भगवत्यै नमः। हे माँ अहोई! मैंने अज्ञानवश साही माता के बच्चों की हत्या की है। मुझे क्षमा करें। मैं आज से यह व्रत करूँगी। मेरे पुत्रों की रक्षा करें और मेरे पाप को क्षमा करें।”\n\nसुभद्रा ने दिनभर निर्जला व्रत रखा। उसने किसी भी जीव को हानि नहीं पहुँचाई। वह माँ अहोई का ध्यान करती रही —\n\n“ॐ अहोई मातायै नमः। साही बच्चों की रक्षा करने वाली माँ, मेरी सहायता करो।”\n\nसायंकाल होते ही सुभद्रा ने दीवार पर गेरू से माँ अहोई का चित्र बनाया। उनके साथ साही माता और उसके पाँच नन्हे बच्चों का चित्र बनाया। उसने माँ अहोई को चूड़ी, बिंदी, महावर, फूल और मिष्ठान अर्पित किए। साही माता के चित्र के सम्मुख गुड़ और चावल रखे।\n\nफिर सुभद्रा ने हाथ जोड़कर माँ अहोई से प्रार्थना की —\n\n“हे माँ अहोई! आप साही माता के बच्चों की अधिष्ठात्री हैं। मैंने अज्ञानवश उन्हें मार डाला। मुझे क्षमा करें। मेरे सातों पुत्रों को जीवनदान दें।”\n\nउसने अहोई अष्टमी की कथा सुनी और आरती गाई —\n\n“अहोई माता दयामयी, साही बच्चों साथ।\nजो व्रत करे श्रद्धा से, उसके सदा सुख हाथ॥”\n\nरात्रि में सुभद्रा ने तारों के दर्शन किए। उसने छलनी से तारे देखे और माँ अहोई को प्रणाम किया। फिर उसने पारण किया। पारण में उसने गुड़, चावल और खीर ग्रहण की।\n\nउस रात सुभद्रा को फिर स्वप्न में माँ अहोई ने दर्शन दिए। उन्होंने कहा —\n\n“पुत्रि! तेरा व्रत सफल हुआ। तूने श्रद्धा से मेरा पूजन किया और साही माता के बच्चों के लिए प्रायश्चित किया। मैं प्रसन्न हूँ। तेरे पुत्रों को जीवनदान दिया जाता है। परन्तु एक बात याद रखना — अब से प्रत्येक वर्ष अहोई अष्टमी का व्रत करना और किसी भी जीव को हानि मत पहुँचाना।”\n\nसुभद्रा ने स्वप्न में हाथ जोड़कर कहा —\n\n“माँ! मैं सदा यह व्रत करूँगी। मैं कभी किसी जीव को हानि नहीं पहुँचाऊँगी।”\n\nप्रातःकाल जब सुभद्रा ने आँखें खोलीं, तो उसने देखा — उसके सातों पुत्र जीवित होकर अपने बिस्तरों पर सो रहे थे! उनके मुख पर वही तेज लौट आया था, जो मृत्यु के बाद छिन गया था। सुभद्रा ने अपनी आँखों पर विश्वास नहीं किया। उसने अपने पुत्रों को गले लगाया और रो पड़ी —\n\n“हे माँ अहोई! आपने मेरे पुत्रों को जीवनदान दिया। मैं आपकी ऋणी हूँ।”\n\nधनपाल ने जब अपने पुत्रों को जीवित देखा, तो वह आनन्द से भर गया। उसने माँ अहोई के चरणों में प्रणाम किया और कहा —\n\n“हे माँ! आपने हमें हमारा सर्वस्व लौटा दिया। अब हम आपके ऋणी हैं।”\n\nसातों पुत्रों ने माता से पूछा —\n\n“माता! हमें क्या हुआ था? हमें तो कुछ याद नहीं।”\n\nसुभद्रा ने अपने पुत्रों को सारी घटना सुनाई — कैसे उसने अज्ञानवश साही के बच्चों को मार डाला, कैसे साही माता ने श्राप दिया, कैसे उसके सातों पुत्र मर गए और कैसे माँ अहोई की कृपा से वे जीवित हो गए।\n\nसातों पुत्रों ने सुना तो उनकी आँखें भर आईं। उन्होंने कहा —\n\n“माता! अब हम प्रतिदिन माँ अहोई का पूजन करेंगे और किसी भी जीव को हानि नहीं पहुँचाएँगे।”\n\nसुभद्रा ने उस दिन से अहोई अष्टमी का व्रत प्रत्येक वर्ष करना आरम्भ किया। उसने अपने घर में माँ अहोई की प्रतिमा स्थापित की और प्रतिदिन उनका पूजन करने लगी। उसने नगर की स्त्रियों को भी यह व्रत सिखाया और उन्हें साही माता के बच्चों की रक्षा का महात्म्य बताया।\n\nपरन्तु सुभद्रा के मन में एक प्रश्न था — “माँ अहोई ने मुझे तो क्षमा कर दिया, परन्तु साही माता का क्या? वह अपने बच्चों के शोक में है। क्या मैं उससे क्षमा माँग सकती हूँ?”\n\nसुभद्रा ने अपने पति धनपाल से कहा —\n\n“स्वामी! मैं साही माता से क्षमा माँगना चाहती हूँ। मुझे उसके पास ले चलिए।”\n\nधनपाल ने कहा —\n\n“पत्नी! साही माता अब भी अपने बच्चों के शोक में होगी। परन्तु तुम्हारा हृदय शुद्ध है। तुम जाओ, मैं तुम्हारे साथ चलूँगा।”\n\nसुभद्रा साही माता के बिल के पास पहुँची। उसने देखा — साही माता अपने बच्चों की याद में बैठी थी। उसकी आँखों से आँसू बह रहे थे। सुभद्रा ने दूर से ही हाथ जोड़कर कहा —\n\n“माता! मैं सुभद्रा हूँ, जिसने तुम्हारे बच्चों को मारा। मैं अपने किए पर लज्जित हूँ। मैंने माँ अहोई की कृपा से अपने पुत्रों को जीवनदान पाया है। अब मैं तुम्हारे बच्चों के लिए प्रायश्चित करना चाहती हूँ। कृपया मुझे क्षमा करो।”\n\nसाही माता ने सुभद्रा को देखा। उसके हृदय में अभी भी शोक था, परन्तु सुभद्रा की करुणा और पश्चाताप उसने देखा। उसने कहा —\n\n“सुभद्रा! तूने मेरे बच्चों को मारा। मेरा शोक कभी कम नहीं होगा। परन्तु तूने अज्ञानवश यह किया और अब तू माँ अहोई की कृपा से अपने पुत्रों को जीवनदान मिला है। मैं तुझे क्षमा करती हूँ। परन्तु तू माँ अहोई का व्रत प्रत्येक वर्ष करना और सभी जीवों की रक्षा का संकल्प लेना।”\n\nसुभद्रा ने हाथ जोड़कर कहा —\n\n“माता! मैं ऐसा ही करूँगी।”\n\nयह कहकर सुभद्रा ने साही माता के लिए गुड़ और चावल अर्पित किए। साही माता ने उन्हें स्वीकार किया और सुभद्रा को आशीर्वाद दिया —\n\n“पुत्रि! तेरे पुत्रों की आयु लम्बी हो। तेरा घर सदा सुख-समृद्धि से भरा रहे।”\n\nउस दिन से सुभद्रा ने साही माता को भी अपने घर में स्थान दिया। उसने दीवार पर साही माता और उसके बच्चों का चित्र बनाया और उन्हें प्रतिदिन प्रणाम किया। यह देखकर नगर की स्त्रियों ने भी अहोई अष्टमी का व्रत करना आरम्भ किया।\n\nएक दिन धनपाल ने सुभद्रा से पूछा —\n\n“पत्नी! माँ अहोई का व्रत मुझे सबसे अद्भुत लगता है। क्या तुम मुझे इस व्रत का सम्पूर्ण महात्म्य बता सकती हो?”\n\nसुभद्रा ने कहा —\n\n“स्वामी! मैं तो केवल इतना जानती हूँ कि यह व्रत पुत्रों की रक्षा करता है और साही माता के बच्चों की हत्या का पाप नष्ट करता है। परन्तु माँ अहोई स्वयं इसका सम्पूर्ण महात्म्य बताएँगी।”\n\nउसी रात सुभद्रा ने माँ अहोई से प्रार्थना की —\n\n“माँ! कृपया मुझे इस व्रत का सम्पूर्ण महात्म्य बताइए, जिससे मैं इसे सभी तक पहुँचा सकूँ।”\n\nमाँ अहोई ने स्वप्न में दर्शन दिए और कहा —\n\n“पुत्रि! कल प्रातः मेरी प्रतिमा के सम्मुख बैठना। मैं तुझे सम्पूर्ण महात्म्य बताऊँगी।”";

    $ch3Title = "माँ अहोई का दिव्य दर्शन और व्रत का रहस्य";
    $ch3Story = "अगली प्रातः सुभद्रा ने स्नान किया, स्वच्छ वस्त्र पहने और अपने घर के उस पवित्र स्थान पर पहुँची, जहाँ उसने दीवार पर माँ अहोई और साही माता के बच्चों का चित्र बनाया था। उसने चित्र के सम्मुख गुड़, चावल और पुष्प रखे, दीपक जलाया और हाथ जोड़कर बैठ गई। उसका हृदय श्रद्धा से भरा हुआ था और आँखों में प्रेम के आँसू थे।\n\nवह प्रार्थना करने लगी —\n\n“ॐ अहोई भगवत्यै नमः। हे माँ! आपने मेरे पुत्रों को जीवनदान दिया। आपने मेरे पाप को क्षमा किया। अब कृपया मुझे इस व्रत का सम्पूर्ण महात्म्य बताइए, जिससे मैं इसे सभी स्त्रियों तक पहुँचा सकूँ।”\n\nतभी दीवार पर बना चित्र अचानक दिव्य प्रकाश से चमकने लगा। सुभद्रा ने आश्चर्य से देखा — चित्र से एक सुन्दर स्त्री प्रकट हुईं। उनका रूप अत्यन्त कोमल और करुणामयी था। उनके मुख पर वात्सल्य की अद्भुत आभा थी, मानो वे सारी सृष्टि की माता हों। उनके एक हाथ में वरद-मुद्रा थी और दूसरे हाथ में अभय-मुद्रा। उनके चारों ओर साही माता और उसके पाँच नन्हे बच्चे खड़े थे — वे सब जीवित और स्वस्थ थे!\n\nसुभद्रा ने दण्डवत प्रणाम किया —\n\n“माँ! आपने मुझे दर्शन दिए। मैं धन्य हूँ।”\n\nमाँ अहोई ने मुस्कुराकर कहा —\n\n“पुत्रि! उठो। तेरी भक्ति और पश्चाताप ने मुझे प्रसन्न किया। तूने अज्ञानवश पाप किया, परन्तु तूने उसका प्रायश्चित किया। तूने साही माता से क्षमा माँगी और उसके बच्चों की रक्षा का संकल्प लिया। यही सच्ची भक्ति है।”\n\nसुभद्रा ने हाथ जोड़कर पूछा —\n\n“माँ! कृपया मुझे इस व्रत का सम्पूर्ण महात्म्य बताइए। यह व्रत कब आरम्भ हुआ? आपका साही माता से क्या सम्बन्ध है? और इस व्रत का फल क्या है?”\n\nमाँ अहोई का प्रादुर्भाव और साही माता:\nमाँ अहोई ने कहा —\n\n“पुत्रि! सुनो, मैं तुम्हें इस व्रत का सम्पूर्ण रहस्य बताती हूँ। सृष्टि के आरम्भ में जब ब्रह्माजी ने सभी प्राणियों की रचना की, तब उन्होंने प्रत्येक जीव को उसके कर्म के अनुसार स्थान दिया। साही (सेह) को उन्होंने वन और भूमि का रक्षक बनाया। साही माता अपने बच्चों की अत्यन्त रक्षा करती है। वह अपने शरीर पर काँटे धारण करती है, जिससे कोई उसके बच्चों को हानि न पहुँचा सके। परन्तु जब कोई मनुष्य अज्ञानवश या हिंसावश उसके बच्चों को मार डालता है, तो साही माता का श्राप अत्यन्त भयंकर होता है।\n\nमैं अहोई भगवती साही माता की अधिष्ठात्री देवी हूँ। मैं उन सभी जीवों की रक्षा करती हूँ, जो निर्दोष हैं और जिनकी कोई रक्षा नहीं करता। जो स्त्री मेरा व्रत करती है, मैं उसके पुत्रों की रक्षा करती हूँ और उसे साही माता के बच्चों की हत्या के पाप से मुक्त करती हूँ।”\n\nसुभद्रा ने पूछा —\n\n“माँ! यह व्रत कब आरम्भ हुआ? क्या आपने इसे स्वयं स्थापित किया?”\n\nमाँ अहोई ने कहा —\n\n“पुत्रि! यह व्रत उस समय आरम्भ हुआ जब सृष्टि के आरम्भ में साही माता के बच्चों की रक्षा का प्रश्न उठा। एक बार वन में एक साधु रहते थे। वे अत्यन्त तपस्वी और करुणामय थे। एक दिन उन्होंने देखा कि एक साही माता अपने बच्चों के लिए विलाप कर रही है। उसके बच्चे किसी शिकारी द्वारा मार दिए गए थे। साधु ने उस साही माता को देखा और उसका शोक देखकर उनका हृदय द्रवित हो गया।\n\nसाधु ने माँ पार्वती से प्रार्थना की —\n\n‘हे माँ! आप सभी जीवों की माता हैं। इस निर्दोष साही माता के बच्चों की रक्षा का कोई उपाय बताइए।’\n\nमाँ पार्वती ने साधु को दर्शन दिए और कहा —\n\n‘वत्स! कार्तिक कृष्ण अष्टमी के दिन जो स्त्री श्रद्धा से मेरा पूजन करेगी और साही माता के बच्चों की रक्षा का संकल्प लेगी, उसके पुत्रों की रक्षा होगी। मैं उस दिन अहोई के रूप में प्रकट होकर उसकी रक्षा करूँगी।’\n\nउसी दिन से अहोई अष्टमी का व्रत प्रारम्भ हुआ। माँ पार्वती ने मुझे इस व्रत की अधिष्ठात्री बनाया और कहा —\n\n‘जो स्त्री इस व्रत को श्रद्धा से करेगी, उसके पुत्रों की रक्षा होगी और साही माता के बच्चों की हत्या का पाप भी नष्ट होगा।’\n\nइसलिए पुत्रि, यह व्रत केवल पुत्र-प्राप्ति का नहीं, बल्कि अहिंसा और करुणा का व्रत है। जो स्त्री यह व्रत करती है, वह सभी जीवों की रक्षा का संकल्प लेती है।”\n\nव्रत की विधि:\nसुभद्रा ने पूछा —\n\n“माँ! कृपया मुझे इस व्रत की सम्पूर्ण विधि बताइए।”\n\nमाँ अहोई ने कहा —\n\n“पुत्रि! सुनो, विधि इस प्रकार है —\n\n1. प्रातः स्नान एवं संकल्प: कार्तिक कृष्ण अष्टमी के दिन प्रातः ब्रह्ममुहूर्त में स्नान करो। स्वच्छ वस्त्र पहनकर मेरे सम्मुख बैठो। हाथ में जल और अक्षत लेकर संकल्प करो — ‘ॐ अहोई भगवत्यै नमः। मैं अपने पुत्रों की रक्षा और सभी जीवों की रक्षा के लिए यह व्रत करती हूँ।’\n\n2. निर्जला या फलाहार व्रत: दिनभर अन्न-जल ग्रहण न करो या फलाहार करो। परन्तु किसी भी जीव को हानि मत पहुँचाओ। क्रोध, हिंसा और निन्दा का त्याग करो।\n\n3. दीवार पर चित्र: सायंकाल दीवार पर गेरू या चूने से मेरा चित्र बनाओ। मेरे साथ साही माता और उसके बच्चों का चित्र बनाओ। मेरे चित्र में सुहाग सामग्री — चूड़ी, बिंदी, महावर — अर्पित करो। साही माता के चित्र के सम्मुख गुड़ और चावल रखो।\n\n4. पूजन: मेरा और साही माता का विधिवत पूजन करो। धूप, दीप, पुष्प, नैवेद्य अर्पित करो। गुड़, चावल, खीर, पूरी और हलवा का भोग लगाओ।\n\n5. कथा श्रवण: मेरी कथा श्रद्धापूर्वक सुनो। इससे व्रत का फल दुगुना हो जाता है।\n\n6. तारों के दर्शन: रात्रि में तारों के दर्शन के बाद पारण करो। छलनी से तारे देखो और मुझे प्रणाम करो। इससे तुम्हारी सभी मनोकामनाएँ पूर्ण होंगी।”\n\nव्रत के नियम:\nसुभद्रा ने पूछा —\n\n“माँ! इस व्रत में किन नियमों का पालन करना चाहिए?”\n\nमाँ अहोई ने कहा —\n\n“पुत्रि! सुनो —\n- व्रत के दिन किसी भी जीव-जन्तु, पशु-पक्षी, कीट-पतंग को हानि मत पहुँचाओ। यह इस व्रत का सबसे महत्वपूर्ण नियम है।\n- किसी भी प्राणी की हत्या मत करो, चाहे वह कितना भी छोटा हो।\n- क्रोध मत करो, किसी की निन्दा मत करो, सत्य बोलो।\n- व्रत के दिन तामसिक भोजन — मांस, मदिरा, लहसुन, प्याज — ग्रहण मत करो।\n- दीवार पर बने चित्र के सम्मुख दीपक अवश्य जलाओ। यह मेरी उपस्थिति का प्रतीक है।\n- व्रत के दिन किसी को अपमानित मत करो। जो अपमान करता है, उसका व्रत निष्फल हो जाता है।\n- यदि किसी कारण से कोई अष्टमी छूट जाए, तो अगले मास की अष्टमी में दोनों की पूर्ति करो।\n- व्रत के दिन दान अवश्य करो — अन्न, वस्त्र या धन, जो भी सम्भव हो।\n- साही माता के बच्चों के लिए गुड़ और चावल अवश्य अर्पित करो। यह उनकी रक्षा का प्रतीक है।\n- व्रत के दिन सभी जीवों के प्रति करुणा का भाव रखो।”\n\nव्रत का फल:\nसुभद्रा ने पूछा —\n\n“माँ! इस व्रत से कौन-कौन से फल प्राप्त होते हैं?”\n\nमाँ अहोई ने कहा —\n\n“पुत्रि! जो स्त्री श्रद्धा और भक्ति से यह व्रत करती है —\n- उसके पुत्रों की रक्षा होती है और उनकी आयु बढ़ती है।\n- सन्तान-सुख की प्राप्ति होती है।\n- साही माता के बच्चों की हत्या का पाप नष्ट हो जाता है।\n- घर में सुख, शान्ति और समृद्धि आती है।\n- किसी भी जीव की हिंसा का पाप नष्ट होता है।\n- पुत्र-प्राप्ति की इच्छा पूर्ण होती है।\n- बालकों के रोग और संकट दूर होते हैं।\n- स्त्री का सौभाग्य अखण्ड रहता है।\n- जो स्त्री सन्तानहीन है, उसे सन्तान-सुख मिलता है।\n- जो स्त्री पुत्र-शोक से पीड़ित है, उसका शोक दूर होता है।\n\nपरन्तु पुत्रि, सबसे बड़ा फल यह है कि जो स्त्री यह व्रत करती है, उसके हृदय में करुणा का वास हो जाता है। वह सभी जीवों को अपने पुत्र के समान देखती है। और जिसके हृदय में करुणा है, उसे माँ अहोई की कृपा सदा प्राप्त रहती है।”\n\nसाही माता का महात्म्य:\nसुभद्रा ने पूछा —\n\n“माँ! साही माता का क्या महात्म्य है? क्या वे भी कोई देवी हैं?”\n\nमाँ अहोई ने मुस्कुराकर कहा —\n\n“पुत्रि! साही माता स्वयं एक देवी हैं। वे वन और भूमि की रक्षक देवी हैं। उनका शरीर काँटों से ढका है, जिसका अर्थ है कि वे अपने बच्चों की रक्षा के लिए स्वयं कष्ट सहती हैं। जो स्त्री उनके बच्चों की रक्षा का संकल्प लेती है, साही माता उसकी सन्तान की रक्षा करती हैं। मैं और साही माता — दोनों मिलकर सभी निर्दोष जीवों की रक्षा करती हैं।”\n\nसुभद्रा ने पूछा —\n\n“माँ! मैंने जो पाप किया, वह क्षमा हो गया। परन्तु मैं चाहती हूँ कि सभी स्त्रियाँ इस व्रत को जानें और कोई भी अज्ञानवश हिंसा का पाप न करे।”\n\nमाँ अहोई ने कहा —\n\n“पुत्रि! तूने यही तो मेरी सच्ची पूजा की है। जो इस कथा को सुनकर दूसरों को सुनाता है, उसका पुण्य अनन्त हो जाता है। अब तू घर जा और अपने पुत्रों के साथ सुख से रह। मैं सदा तुम्हारी रक्षा करूँगी।”\n\nयह कहकर माँ अहोई अन्तर्धान हो गईं। साही माता ने सुभद्रा को आशीर्वाद दिया और अपने बच्चों के साथ वहाँ से चली गई।\n\nसुभद्रा ने उस दिन से अहोई अष्टमी का व्रत प्रत्येक वर्ष करना आरम्भ किया। उसने सभी स्त्रियों को इस व्रत का महात्म्य बताया और उन्हें साही माता के बच्चों की रक्षा का संकल्प दिलाया।\n\nपरन्तु सुभद्रा के मन में एक और प्रश्न था — “माँ अहोई ने मुझे तो सब कुछ बता दिया, परन्तु मैं चाहती हूँ कि यह कथा सभी तक पहुँचे और कोई भी स्त्री अज्ञानवश हिंसा का पाप न करे। मैं क्या करूँ?”\n\nउसने अपने पति धनपाल से कहा —\n\n“स्वामी! मैं चाहती हूँ कि इस व्रत का महात्म्य सभी स्त्रियों तक पहुँचे। क्या आप मेरी सहायता करेंगे?”\n\nधनपाल ने कहा —\n\n“पत्नी! यह तो अत्यन्त पुण्य का कार्य है। मैं तुम्हारे साथ हूँ। हम मिलकर इस व्रत का प्रचार करेंगे।”\n\nइस प्रकार सुभद्रा और धनपाल ने नगर में अहोई अष्टमी व्रत का प्रचार किया। सभी स्त्रियाँ श्रद्धा से यह व्रत करने लगीं और माँ अहोई की कृपा से उनके पुत्रों की रक्षा होने लगी।\n\nएक दिन सुभद्रा ने अपनी सास से पूछा —\n\n“माता! अब मैं जानना चाहती हूँ कि इस व्रत का अन्तिम फल क्या है? जो स्त्री यह व्रत करती है, उसे अन्त में क्या प्राप्त होता है?”\n\nसास ने कहा —\n\n“पुत्रि! माँ अहोई ने तो तुझे सब कुछ बता दिया। परन्तु मैं इतना जानती हूँ कि जो स्त्री यह व्रत करती है, उसे सन्तान-सुख और सौभाग्य की प्राप्ति होती है। तू स्वयं माँ अहोई से प्रार्थना कर, वे तुझे अन्तिम फल बताएँगी।”";

    $ch4Title = "व्रत का महात्म्य, फलश्रुति एवं समापन";
    $ch4Story = "उस रात सुभद्रा ने माँ अहोई से प्रार्थना की —\n\n“माँ! आपने मुझे व्रत की विधि और नियम बताए। अब कृपया मुझे इस व्रत का अन्तिम फल और महात्म्य बताइए, जिससे मैं इसे सभी स्त्रियों तक पहुँचा सकूँ और उन्हें भी आपकी कृपा प्राप्त हो।”\n\nरात्रि के अन्तिम प्रहर में सुभद्रा को माँ अहोई ने पुनः दर्शन दिए। इस बार उनके साथ साही माता और उनके पाँचों बच्चे भी थे। माँ अहोई ने कहा —\n\n“पुत्रि! तेरा प्रश्न उत्तम है। सुनो, मैं तुझे इस व्रत का सम्पूर्ण महात्म्य और फलश्रुति बताती हूँ।”\n\nव्रत का महात्म्य:\nमाँ अहोई बोलीं —\n\n“पुत्रि! अहोई अष्टमी का व्रत केवल एक दिन का व्रत नहीं है। यह अहिंसा, करुणा और मातृत्व का व्रत है। जो स्त्री यह व्रत करती है, वह केवल अपने पुत्रों की रक्षा नहीं करती, बल्कि सभी जीवों की रक्षा का संकल्प लेती है।\n\nइस व्रत का सबसे बड़ा रहस्य यह है कि यह साही माता से जुड़ा है। साही माता वन और भूमि की रक्षक देवी हैं। वे अपने शरीर पर काँटे धारण करती हैं — यह काँटे केवल रक्षा के प्रतीक नहीं हैं, बल्कि यह दर्शाते हैं कि माँ अपने बच्चों की रक्षा के लिए स्वयं कष्ट सहती है। जो स्त्री इस व्रत को करती है, वह साही माता के इस त्याग और ममता का स्मरण करती है।\n\nइस व्रत में दीवार पर चित्र बनाना अत्यन्त महत्वपूर्ण है। दीवार पर बना चित्र केवल एक चित्र नहीं है — वह मेरी उपस्थिति का प्रतीक है। जब तुम गेरू से मेरा चित्र बनाती हो, तब तुम अपने हृदय में मुझे स्थापित करती हो। जब तुम साही माता और उसके बच्चों का चित्र बनाती हो, तब तुम सभी जीवों के प्रति करुणा का भाव जगाती हो।\n\nइस व्रत में तारों के दर्शन का विशेष महत्व है। तारे उस अनन्त का प्रतीक हैं, जिसमें सभी जीव समाए हुए हैं। जब तुम छलनी से तारे देखती हो, तब तुम यह स्वीकार करती हो कि तुम्हारा जीवन भी उसी अनन्त का एक छोटा-सा अंश है। यह विनम्रता का प्रतीक है।\n\nइस व्रत में गुड़ और चावल का भोग साही माता के बच्चों को अर्पित किया जाता है। यह इस बात का प्रतीक है कि हम प्रकृति के प्रत्येक जीव के प्रति अपनी कृतज्ञता व्यक्त करते हैं।”\n\nव्रत के प्रकार:\nमाँ अहोई ने कहा —\n\n“पुत्रि! यह व्रत तीन प्रकार से किया जाता है —\n\nनिर्जला व्रत: जो स्त्री पूर्ण निर्जला व्रत करती है, उसे इस व्रत का सर्वोच्च फल प्राप्त होता है।\nफलाहार व्रत: जो स्त्री फलाहार करती है, उसे भी पूर्ण फल प्राप्त होता है।\nएक समय भोजन: जो स्त्री एक समय भोजन करती है, उसे भी इस व्रत का फल प्राप्त होता है।\n\nपरन्तु सबसे महत्वपूर्ण है अहिंसा का पालन। यदि कोई स्त्री निर्जला व्रत करके भी किसी जीव को हानि पहुँचाती है, तो उसका व्रत निष्फल हो जाता है। और यदि कोई स्त्री फलाहार करके भी सभी जीवों की रक्षा का संकल्प लेती है, तो उसका व्रत सफल हो जाता है।”\n\nव्रत का फल:\nसुभद्रा ने पूछा —\n\n“माँ! इस व्रत का फल क्या है? जो स्त्री यह व्रत करती है, उसे क्या-क्या लाभ मिलते हैं?”\n\nमाँ अहोई ने कहा —\n\n“पुत्रि! जो स्त्री श्रद्धा और भक्ति से यह व्रत करती है —\n\nउसके पुत्रों की आयु बढ़ती है और उनकी रक्षा होती है।\nसन्तान-सुख की प्राप्ति होती है।\nसाही माता के बच्चों की हत्या का पाप नष्ट हो जाता है।\nकिसी भी जीव की हिंसा का पाप नष्ट होता है।\nघर में सुख, शान्ति और समृद्धि आती है।\nपुत्र-प्राप्ति की इच्छा पूर्ण होती है।\nबालकों के रोग और संकट दूर होते हैं।\nस्त्री का सौभाग्य अखण्ड रहता है।\nजो स्त्री सन्तानहीन है, उसे सन्तान-सुख मिलता है।\nजो स्त्री पुत्र-शोक से पीड़ित है, उसका शोक दूर होता है।\nजो स्त्री अपने पुत्रों के भविष्य के लिए चिन्तित है, उसकी चिन्ता दूर होती है।\nजो स्त्री किसी रोग से पीड़ित है, उसे रोग से मुक्ति मिलती है।\nजो स्त्री अहिंसा का पालन करती है, उसे माँ अहोई की विशेष कृपा प्राप्त होती है।\nजो स्त्री यह व्रत करती है, उसे अन्त में मेरे लोक की प्राप्ति होती है।\n\nपरन्तु पुत्रि, सबसे बड़ा फल यह है कि जो स्त्री यह व्रत करती है, उसके हृदय में करुणा और ममता का वास हो जाता है। वह सभी जीवों को अपने पुत्र के समान देखती है। और जिसके हृदय में करुणा है, उसे माँ अहोई की कृपा सदा प्राप्त रहती है।”\n\nसन्तानहीन स्त्रियों के लिए विशेष विधान:\nसुभद्रा ने पूछा —\n\n“माँ! जो स्त्री सन्तानहीन है, वह क्या करे?”\n\nमाँ अहोई ने कहा —\n\n“पुत्रि! जो स्त्री सन्तान की इच्छा रखती है, उसे यह व्रत विशेष रूप से करना चाहिए। उसे प्रत्येक अष्टमी को व्रत करना चाहिए और मेरी प्रतिमा के सम्मुख सन्तान की प्रार्थना करनी चाहिए। उसे साही माता के बच्चों के लिए गुड़ और चावल अवश्य अर्पित करना चाहिए। जो स्त्री श्रद्धा से यह व्रत करती है, उसे सन्तान-सुख अवश्य प्राप्त होता है।”\n\nपुत्र-शोक से पीड़ित स्त्रियों के लिए विशेष विधान:\nसुभद्रा ने पूछा —\n\n“माँ! जो स्त्री पुत्र-शोक से पीड़ित है, वह क्या करे?”\n\nमाँ अहोई ने कहा —\n\n“पुत्रि! जो स्त्री पुत्र-शोक से पीड़ित है, उसे यह व्रत विशेष रूप से करना चाहिए। उसे साही माता के बच्चों के लिए विशेष रूप से गुड़ और चावल अर्पित करना चाहिए और उनकी रक्षा का संकल्प लेना चाहिए। मैं उसके पुत्र-शोक को दूर करती हूँ और उसे सन्तान-सुख प्रदान करती हूँ। जैसे मैंने तेरे पुत्रों को जीवनदान दिया, वैसे ही मैं उसके पुत्रों को भी जीवनदान दूँगी।”\n\nफलश्रुति:\nमाँ अहोई ने कहा —\n\n“पुत्रि! जो व्यक्ति इस अहोई अष्टमी व्रत कथा को श्रद्धापूर्वक सुनता है, वह इस व्रत का सम्पूर्ण फल प्राप्त करता है। जो स्त्री इस कथा को सुनकर व्रत करती है, उसके पुत्रों की रक्षा होती है और उसे सन्तान-सुख की प्राप्ति होती है। जो कन्या इस कथा को सुनती है, उसे योग्य पुत्र की प्राप्ति होती है। जो पुरुष इस कथा को सुनता है, उसके पुत्रों की रक्षा होती है।\n\nजो इस कथा को पढ़ता या सुनाता है, उसे माँ अहोई की विशेष कृपा प्राप्त होती है। यह कथा जिस घर में सुनी जाती है, वहाँ सुख, समृद्धि और शान्ति बनी रहती है। जो इस कथा को प्रत्येक अष्टमी में सुनता है, उसकी सभी मनोकामनाएँ पूर्ण होती हैं।\n\nजो स्त्री यह व्रत करती है, उसे अहिंसा का पालन अवश्य करना चाहिए। यदि वह किसी भी जीव को हानि पहुँचाती है, तो उसका व्रत निष्फल हो जाता है। इसलिए सभी स्त्रियों को चाहिए कि वे इस व्रत के दिन किसी भी जीव को हानि न पहुँचाएँ और सभी जीवों की रक्षा का संकल्प लें।”\n\nसमापन:\nइसके बाद माँ अहोई ने सुभद्रा को आशीर्वाद दिया —\n\n“पुत्रि! तेरे पुत्रों की आयु लम्बी हो। तेरा घर सदा सुख-समृद्धि से भरा रहे। तूने जो यह व्रत किया, वह सदा तेरे कुल की रक्षा करेगा। अब तू घर जा और अपने पुत्रों के साथ सुख से रह। मैं सदा तुम्हारी रक्षा करूँगी।”\n\nयह कहकर माँ अहोई अन्तर्धान हो गईं। साही माता ने भी सुभद्रा को आशीर्वाद दिया और अपने बच्चों के साथ चली गई।\n\nसुभद्रा ने प्रातःकाल अपनी सास को सारी बात बताई। सास ने कहा —\n\n“पुत्रि! तू धन्य है। माँ अहोई ने तुझे स्वयं दर्शन दिए। अब तू सभी स्त्रियों को इस व्रत का महात्म्य बता।”\n\nसुभद्रा ने उस दिन से अहोई अष्टमी का व्रत प्रत्येक वर्ष करना आरम्भ किया। उसने सभी स्त्रियों को इस व्रत का महात्म्य बताया और उन्हें साही माता के बच्चों की रक्षा का संकल्प दिलाया। सभी स्त्रियाँ श्रद्धा से यह व्रत करने लगीं और माँ अहोई की कृपा से उनके पुत्रों की रक्षा होने लगी।\n\nधीरे-धीरे यह व्रत सारे नगर में प्रसिद्ध हो गया। हर घर की दीवार पर माँ अहोई का चित्र बनने लगा और साही माता के बच्चों के लिए गुड़-चावल अर्पित होने लगे। नगर में अहिंसा और करुणा का भाव जागृत हुआ। लोग अब किसी भी जीव को हानि नहीं पहुँचाते थे।\n\nसुभद्रा और धनपाल ने अपने सातों पुत्रों को भी यह व्रत सिखाया। उनके पुत्रों ने भी सभी जीवों की रक्षा का संकल्प लिया और माँ अहोई की भक्ति में लग गए।\n\nइस प्रकार सुभद्रा का जीवन धन्य हो गया। जिस स्त्री ने अज्ञानवश पाप किया था, वही स्त्री माँ अहोई की कृपा से पापमुक्त होकर सबके लिए आदर्श बन गई।\n\nइति श्री अहोई अष्टमी व्रत कथा सम्पूर्णम्।\n\nॐ अहोई भगवत्यै नमः।\nया देवी सर्वभूतेषु मातृरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥";

